# Viva deep redo — slot R2 (part B): tinea capitis, tinea pedis & onychomycosis, pityriasis versicolor, candidiasis, pediculosis, scabies
# Own words. Topics guided by the previous-year question book (Sahana P Raju) — fungal and infestation chapters;
# facts checked with IADVL 5e.
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"

D = [
dict(case="Tinea capitis", src=f"{PYQ}; {IA} (Superficial fungal infections)",
 qa=[
 ("Who gets tinea capitis and why mostly children?", ["Prepubertal children (3–7 years); rare after puberty because sebum fatty acids (fungistatic) increase", "Adults: post-menopausal women, immunosuppressed"]),
 ("Classify tinea capitis by hair invasion (PYQ).", ["Ectothrix: arthroconidia outside the shaft, cuticle destroyed — Microsporum (M. canis, M. audouinii; fluoresce green) and T. mentagrophytes, T. verrucosum (non-fluorescent large-spored)", "Endothrix: arthroconidia inside the shaft, cuticle intact — T. tonsurans, T. violaceum (commonest in India), T. soudanense; 'black dot' type; non-fluorescent", "Favic: T. schoenleinii — hyphae and air spaces inside hair; dull green fluorescence"]),
 ("Describe the clinical types.", ["Non-inflammatory: grey patch (Microsporum — scaly round patches with broken dull hairs), black dot (endothrix — hairs break at scalp surface), seborrhoeic/diffuse scaling type (mimics dandruff), alopecia areata-like", "Inflammatory: kerion (boggy, tender, pustular mass with loose hairs, lymphadenopathy — zoophilic species; may scar), agminate folliculitis", "Favus: yellow cup-shaped crusts (scutula) around hairs, mousy odour, scarring alopecia"]),
 ("What is a kerion? Should it be incised?", ["Intense delayed-type hypersensitivity reaction to zoophilic/geophilic dermatophytes producing a painful boggy swelling with pus-discharging follicles", "Do not incise (it is not bacterial abscess); treat with systemic antifungal ± short oral steroid for severe inflammation; can cause scarring alopecia"]),
 ("Investigations.", ["Wood's lamp: green (Microsporum), dull green (favus), none (Trichophyton)", "KOH mount of plucked hairs and scales — ecto/endothrix spores", "Culture of hairs/scales (brush or cotton swab method) to identify species — important for choice of drug and to trace animal source", "Trichoscopy: comma hairs, corkscrew hairs, zig-zag hairs, Morse-code hairs, broken/black dots, bar-code hairs"]),
 ("Differential diagnosis.", ["Seborrhoeic dermatitis, psoriasis (silvery scales, hairs intact), alopecia areata (no scaling, exclamation-mark hairs), trichotillomania (bizarre shapes, hairs of varying length), pityriasis amiantacea, atopic dermatitis, impetigo/folliculitis (kerion), discoid lupus, lichen planopilaris, secondary syphilis (moth-eaten alopecia)"]),
 ("Treatment — choose the drug by organism.", ["Oral therapy is always needed (topicals do not penetrate the follicle)", "Griseofulvin (ultra-micro/micro) 20–25 mg/kg/day for 6–8 weeks (or longer) with fatty meal — best for Microsporum", "Terbinafine by weight for 2–4 weeks (Trichophyton) — <20 kg 62.5 mg, 20–40 kg 125 mg, >40 kg 250 mg/day; Microsporum needs longer", "Itraconazole 5 mg/kg/day 4–6 weeks or pulses; fluconazole 6 mg/kg/day 3–6 weeks", "Adjunct: ketoconazole 2%/selenium sulphide 2.5% shampoo twice weekly for patient and family to reduce spore shedding", "Examine and treat household contacts and pets; children can attend school once on treatment"]),
 ("Side effects of griseofulvin.", ["Headache, GI upset, photosensitivity, urticaria, lupus flare, porphyria precipitation, enzyme inducer (reduces OCP and warfarin effect), disulfiram-like reaction with alcohol; avoid in pregnancy and men should avoid fathering a child for 6 months"]),
 ("Endpoint of treatment?", ["Mycological cure (negative KOH and culture), not just clinical improvement"]),
 ("What is tinea capitis in adults like?", ["Often atypical, diffuse scaling or mimics seborrhoeic dermatitis, folliculitis decalvans or DLE; usually Trichophyton (T. violaceum, T. tonsurans)"]),
 ("What is the id reaction in tinea capitis?", ["Itchy papulovesicular eruption on face/trunk after starting treatment of kerion — immune hypersensitivity, not drug allergy; continue antifungal, topical steroid"]),
 ("Prognosis of kerion?", ["Heals with variable permanent scarring alopecia if treatment is delayed"]),
 ],
 spot=["Black dots in a patch of alopecia — endothrix (T. violaceum/tonsurans)", "Boggy pustular scalp mass — kerion (don't incise)", "Scutula + mousy odour — favus"]),

dict(case="Tinea pedis & onychomycosis", src=f"{PYQ}; {IA} (Superficial fungal infections, nail infections)",
 qa=[
 ("Clinical types of tinea pedis.", ["Interdigital (commonest; 4th web space; maceration, fissuring, scaling) — dermatophyte complex with bacteria (Gram-negative 'dermatophytosis complex')", "Moccasin (chronic hyperkeratotic, T. rubrum; diffuse fine scaling of soles and sides)", "Vesiculobullous (inflammatory, instep, T. mentagrophytes/interdigitale)", "Acute ulcerative (Gram-negative superinfection)", "'Two feet, one hand' syndrome — tinea pedis with tinea manuum of one hand"]),
 ("Risk factors for tinea pedis.", ["Occlusive footwear, sweating, communal bathing/swimming pools, sports, diabetes, peripheral vascular disease, immunosuppression"]),
 ("Differential diagnosis of tinea pedis.", ["Interdigital: erythrasma (coral-red), candidal intertrigo, Gram-negative infection, soft corn", "Plantar: psoriasis, keratoderma, contact dermatitis (dorsum), dyshidrotic eczema, juvenile plantar dermatosis, pitted keratolysis"]),
 ("Define onychomycosis. Organisms?", ["Fungal infection of the nail unit — dermatophytes (tinea unguium; T. rubrum, T. interdigitale) ~ 70–90% in toenails, non-dermatophyte moulds (Scopulariopsis, Fusarium, Aspergillus, Neoscytalidium) and Candida (fingernails, chronic paronychia)"]),
 ("Classify onychomycosis by clinical pattern (PYQ).", ["Distal lateral subungual (DLSO) — commonest; invasion via hyponychium; subungual hyperkeratosis, onycholysis, yellow discolouration", "Proximal subungual (PSO) — through proximal nail fold; white under proximal nail; marker of HIV/immunosuppression (T. rubrum) or moulds (Fusarium with paronychia)", "Superficial white (SWO) — chalky white patches on the nail surface (T. interdigitale, moulds); superficial black variant", "Endonyx — milky white nail without hyperkeratosis (T. soudanense, T. violaceum)", "Total dystrophic — end stage", "Mixed patterns; Candida onychomycosis (with chronic paronychia; CMC — total dystrophy)", "Dermatophytoma — yellow/white longitudinal streak or patch (fungal ball) — poor response"]),
 ("How do you sample a nail for diagnosis?", ["Clean with alcohol; take subungual debris from the most proximal part of the affected area (DLSO), scrape the surface (SWO), punch/drill proximal plate (PSO)", "KOH 20–40% (± DMSO), wait or warm; culture on SDA with and without cycloheximide (moulds need the latter)", "Nail clipping histology with PAS — most sensitive single test", "PCR; dermoscopy (spiked/jagged proximal border of onycholysis, longitudinal streaks, 'aurora borealis' pattern)", "Non-dermatophyte mould is accepted as cause only when repeatedly isolated / seen in direct microscopy"]),
 ("Differential diagnosis of nail dystrophy.", ["Nail psoriasis (pits, oil-drop sign, onycholysis with red border, salmon patch), lichen planus (pterygium, thinning), traumatic onychodystrophy (shoe pressure), yellow nail syndrome, onychogryphosis, eczema, subungual tumours (SCC, melanoma), pachyonychia congenita, Darier's disease"]),
 ("Systemic treatment of onychomycosis.", ["Terbinafine 250 mg/day — 6 weeks fingernails, 12 weeks toenails (drug of choice for dermatophyte)", "Itraconazole pulse: 200 mg twice daily for 1 week every month — 2 pulses fingernails, 3–4 toenails (also covers Candida and some moulds); or continuous 200 mg/day", "Fluconazole 150–450 mg once weekly for 6–12 months (fingernails 6, toenails 9–12)", "Efficacy assessed at 12–18 months as nail grows out (toenail grows ~1 mm/month)"]),
 ("Topical treatment of onychomycosis.", ["For mild DLSO (<50% nail, no matrix involvement), SWO, children, or with oral therapy", "Amorolfine 5% lacquer weekly; ciclopirox 8% lacquer daily; efinaconazole 10% solution; tavaborole 5% (US approvals)", "Adjuncts: nail avulsion (chemical with 40% urea or surgical), debridement, laser and photodynamic therapy (limited evidence)"]),
 ("What are the poor prognostic factors?", ["Matrix involvement, >50% nail affected, dermatophytoma, lateral edge disease, thick nail plate (>2 mm), slow growth, elderly, diabetes, peripheral vascular disease, immunosuppression, non-dermatophyte moulds"]),
 ("What is Scytalidium/Neoscytalidium infection?", ["Non-dermatophyte mould causing moccasin-like tinea and onychomycosis in tropics; resistant to most antifungals; cycloheximide sensitive (grows only on media without it)"]),
 ("Prevention of recurrence?", ["Treat tinea pedis, dry feet and web spaces, antifungal powder in shoes, change socks, avoid barefoot in communal areas, discard old footwear, treat family members, periodic topical (amorolfine) use"]),
 ],
 spot=["Proximal white subungual onychomycosis — screen for HIV", "Terbinafine 6 weeks fingernail / 12 weeks toenail", "Dermatophytoma — streak in nail, needs removal + oral therapy"]),

dict(case="Pityriasis versicolor", src=f"{PYQ}; {IA} (Superficial fungal infections — Malassezia)",
 qa=[
 ("What is pityriasis versicolor? Agent?", ["Chronic, recurrent, superficial infection of stratum corneum by Malassezia (lipophilic yeast, normal skin flora) in its mycelial phase — mostly M. globosa, also M. furfur, M. sympodialis", "Not contagious; endogenous overgrowth"]),
 ("Predisposing factors?", ["Hot humid climate, sweating, oily skin, adolescents and young adults (high sebum), oily applications, occlusion, malnutrition, steroids, immunosuppression, pregnancy, genetic predisposition"]),
 ("Clinical features.", ["Multiple round/oval scaly macules coalescing into patches on upper trunk, neck, upper arms, face (children); minimal itch", "Colour: hypopigmented (most common in Indian skin), hyperpigmented (fawn/brown), erythematous — hence 'versicolor'", "Evoked scale sign (Besnier's sign) — stretching or scratching produces fine branny scale"]),
 ("Why are lesions hypopigmented?", ["Azelaic acid and other dicarboxylic acids from Malassezia inhibit tyrosinase; pityriacitrin screens UV; damage to melanocytes and smaller melanosomes; persists for weeks after cure"]),
 ("Why hyperpigmented in some?", ["Larger melanosomes and thicker keratin layer with inflammatory infiltrate"]),
 ("Investigations.", ["KOH mount: short hyphae and round spores — 'spaghetti and meatballs'", "Wood's lamp: yellow-gold fluorescence (not always)", "Scotch tape test with methylene blue/Parker ink; culture needs olive oil-supplemented media (rarely needed)"]),
 ("Differential diagnosis.", ["Hypopigmented: pityriasis alba, vitiligo (depigmented, no scale), indeterminate leprosy (sensation), post-inflammatory hypopigmentation, progressive macular hypomelanosis (no scale, red fluorescence of follicles), nevus depigmentosus, seborrhoeic dermatitis", "Hyperpigmented/red: pityriasis rosea, tinea corporis, seborrhoeic dermatitis, erythrasma, confluent and reticulated papillomatosis, secondary syphilis, café-au-lait"]),
 ("Treatment.", ["Topical: ketoconazole 2% shampoo/lotion applied for 5–10 min daily for 3–5 days; selenium sulphide 2.5%; azole creams; terbinafine cream; zinc pyrithione; 20% sodium hyposulphite", "Oral for extensive or recurrent: itraconazole 200 mg/day for 5–7 days, fluconazole 300 mg weekly for 2 weeks (or 400 mg single dose); oral terbinafine is not effective; griseofulvin not effective", "Counsel that pigment takes months to normalise — not treatment failure"]),
 ("Prophylaxis for recurrence?", ["Ketoconazole/selenium shampoo once or twice monthly or weekly in summer; or itraconazole 400 mg once a month during humid months"]),
 ("Other Malassezia-related diseases?", ["Seborrhoeic dermatitis, Malassezia (Pityrosporum) folliculitis, confluent and reticulated papillomatosis (debated), atopic head-and-neck dermatitis, catheter-related fungaemia in neonates on lipid infusions"]),
 ],
 spot=["Spaghetti and meatballs on KOH", "Evoked scale (Besnier's) sign", "Oral terbinafine doesn't work in PV"]),

dict(case="Cutaneous candidiasis / intertrigo", src=f"{PYQ}; {IA} (Candidiasis)",
 qa=[
 ("What is candidiasis? Main species?", ["Infection by Candida (yeast; commensal of gut, mouth, vagina) when local or systemic defences fail — C. albicans (commonest); non-albicans: C. glabrata, C. tropicalis, C. parapsilosis, C. krusei (fluconazole resistant), Candida auris (multidrug-resistant, hospital outbreaks)", "Dimorphic: yeast, pseudohyphae and true hyphae (in tissue)"]),
 ("Predisposing factors.", ["Local: moisture, occlusion, obesity, maceration, friction, dentures, wet work, diapers", "Systemic: diabetes, pregnancy, infancy/old age, antibiotics, steroids, OCP, HIV, immunosuppression, iron deficiency, endocrinopathies (hypoparathyroidism, hypothyroidism, Addison's)"]),
 ("Clinical forms of mucocutaneous candidiasis.", ["Oral: pseudomembranous (thrush, removable white plaques), erythematous (atrophic — antibiotic/denture), hyperplastic (leukoplakia-like), angular cheilitis, median rhomboid glossitis", "Genital: vulvovaginitis (curdy discharge, itching), balanoposthitis (diabetics, uncircumcised)", "Skin: intertrigo (flexures), napkin candidiasis, interdigital (erosio interdigitalis blastomycetica — 3rd web space of hand in wet workers), chronic paronychia, onychomycosis", "Chronic mucocutaneous candidiasis (CMC); congenital and neonatal candidiasis; disseminated candidiasis (nodules in neutropenic patients)"]),
 ("Describe candidal intertrigo.", ["Bright beefy-red moist glazed patches in folds (groin, submammary, axillae, abdominal folds) with fissure at the base, peripheral scaling (collarette) and satellite papulopustules", "Burning/itching; scrotum often involved (unlike tinea cruris)"]),
 ("Differential diagnosis of intertrigo.", ["Tinea cruris (active edge, scrotum spared), erythrasma (brown, coral-red fluorescence), inverse psoriasis (well-defined, no satellites), seborrhoeic dermatitis, irritant/allergic contact dermatitis, Hailey–Hailey disease, Langerhans cell histiocytosis (infants), extramammary Paget's (elderly, persistent)"]),
 ("What is chronic mucocutaneous candidiasis (CMC)?", ["Group of disorders with persistent/recurrent Candida infections of skin, nails and mucosa due to defective Th17 immunity", "Causes: STAT1 gain-of-function, IL-17RA/IL-17F, CARD9 deficiency, AIRE mutation (APECED/APS-1 — with hypoparathyroidism, Addison's), hyper-IgE (STAT3); thymoma", "Treatment: long-term azoles, treat endocrinopathy"]),
 ("Investigations.", ["KOH/Gram stain: budding yeasts with pseudohyphae (pseudohyphae suggest invasion)", "Culture on SDA (creamy colonies); germ tube test (C. albicans positive), CHROMagar for species, antifungal susceptibility for recurrent/non-albicans", "Blood sugar, HIV; in CMC — immunology and endocrine work-up"]),
 ("Treatment of cutaneous candidiasis.", ["Keep area dry, separate folds with cotton cloth, weight loss, control diabetes, treat source (oral/gut)", "Topical azoles (clotrimazole, miconazole, ketoconazole), nystatin, ciclopirox; short mild steroid combination only if very inflamed", "Oral fluconazole 150 mg weekly/50–100 mg daily for 1–2 weeks for extensive or recurrent; itraconazole alternative"]),
 ("Treatment of vulvovaginal candidiasis.", ["Clotrimazole 500 mg vaginal pessary single dose or 100 mg for 6 nights, or fluconazole 150 mg oral single dose (avoid oral in pregnancy — use topical 7 days)", "Recurrent (≥4/year): fluconazole 150 mg every 72 h × 3 doses, then weekly for 6 months; C. glabrata — boric acid vaginal capsules"]),
 ("What is chronic paronychia and its management?", ["Inflammation of proximal nail fold >6 weeks in wet workers; loss of cuticle, bolstered red fold, nail dystrophy; now considered mainly an irritant/eczematous process with Candida as secondary", "Keep hands dry, gloves, topical steroid + azole, treat Candida, avoid cuticle trimming"]),
 ("What is Candida auris and why important?", ["Emerging multidrug-resistant yeast, hospital outbreaks, colonises skin, often misidentified by routine methods; needs echinocandin and strict infection control"]),
 ],
 spot=["Beefy-red fold with satellite pustules and scrotal involvement — candidal intertrigo", "Erosio interdigitalis blastomycetica — 3rd finger web", "Pseudohyphae on KOH"]),

dict(case="Pediculosis", src=f"{PYQ}; {IA} (Infestations)",
 qa=[
 ("Name the lice that infest humans.", ["Pediculus humanus capitis (head louse), Pediculus humanus corporis (body louse), Pthirus pubis (crab/pubic louse)", "Obligate blood-sucking ectoparasites; wingless, dorsoventrally flattened, six legs with claws"]),
 ("Describe the life cycle.", ["Egg (nit) cemented to the hair shaft close to scalp → hatches in 7–10 days → three nymph stages over ~9–12 days → adult lives ~30 days; female lays 5–10 eggs/day", "Lice die away from host in 1–2 days (head louse)"]),
 ("Clinical features of pediculosis capitis.", ["Children (girls more), itching of scalp esp. occiput and behind ears, excoriations, secondary impetigo, occipital/cervical lymphadenopathy", "Nits: ovoid grey-white 0.8 mm, firmly attached, cannot be flicked off (unlike dandruff/hair casts)", "Heavy infestation: matted hair ('plica polonica'), id-like papular eruption on neck"]),
 ("Differentiate nits from hair casts and dandruff.", ["Nits: eccentrically cemented oval structures on one side of hair, not movable", "Hair casts (pseudonits): tubular keratin sheaths encircling the hair, slide freely along the shaft", "Dandruff: loose flakes easily shaken off; also piedra (hard nodules — fungal), trichorrhexis nodosa, hair spray droplets"]),
 ("Describe pediculosis corporis.", ["Body lice live in clothing seams, visit skin to feed — seen in poverty, homelessness, refugees, overcrowding", "Itching, excoriations, hyperpigmented thickened skin ('vagabond's disease'), maculae caeruleae", "Vector of epidemic typhus (Rickettsia prowazekii), trench fever (Bartonella quintana), relapsing fever (Borrelia recurrentis)", "Treatment: hygiene and laundering of clothing at ≥60 °C — no need to treat the body usually"]),
 ("Describe pediculosis pubis.", ["Sexually transmitted; pubic, perianal, axillary hair, beard, eyelashes (children — consider abuse)", "Itching, lice and nits at hair roots, maculae caeruleae (slate-blue macules from louse saliva on thighs and trunk)", "Screen for other STIs; treat partners"]),
 ("Investigations.", ["Wet combing with a fine-toothed comb (most reliable to detect live lice)", "Dermoscopy: live nymphs, viable nits (oval with operculum) vs empty nits (translucent with flat cut end)", "Live louse = active infestation; nits >1 cm from scalp may be old"]),
 ("Treatment of head lice.", ["Topical pediculicides — 2 applications 7–10 days apart (second kills newly hatched nymphs):", "Permethrin 1% cream rinse (10 min), dimeticone 4% (physical — no resistance; preferred where resistance is common), malathion 0.5%, ivermectin 0.5% lotion (single application), spinosad 0.9%, benzyl alcohol 5%, abametapir", "Oral ivermectin 400 µg/kg on days 1 and 8 for resistant cases (>15 kg)", "Wet combing every 3–4 days for 2 weeks; remove nits with fine comb/vinegar rinse; wash pillowcases, combs, hats in hot water; treat all affected household members"]),
 ("Treatment of eyelash infestation (phthiriasis palpebrarum).", ["Occlusive petrolatum twice daily for 8–10 days, mechanical removal, or oral ivermectin; pediculicides not used near the eyes"]),
 ("Why is lindane no longer used?", ["Neurotoxicity (seizures) especially in children and with misuse; banned/withdrawn in many countries including India (please confirm current status)"]),
 ("Causes of treatment failure?", ["Resistance (kdr mutations to permethrin), wrong application, reinfestation from untreated contacts, no second application, misdiagnosis of dead nits as active infestation"]),
 ],
 spot=["Nits firmly cemented on one side of hair shaft", "Maculae caeruleae — pubic lice", "Body louse — vector of epidemic typhus, trench fever, relapsing fever"]),

dict(case="Scabies", src=f"{PYQ}; {IA} (Infestations — scabies); WHO / IACS guidance on scabies",
 qa=[
 ("What is scabies? Describe the mite.", ["Intensely itchy contagious infestation by the mite Sarcoptes scabiei var. hominis", "Female ~0.4 mm, burrows in stratum corneum, lays 2–3 eggs/day for 4–6 weeks; eggs hatch in 3–4 days; larva → nymph → adult in ~10–14 days", "Average 10–15 mites per patient in classic scabies; thousands to millions in crusted scabies; mites survive off host 24–36 h (longer in cool humid)"]),
 ("How is it transmitted?", ["Prolonged skin-to-skin contact (family, sexual, care homes); fomites matter mainly for crusted scabies", "Incubation 3–6 weeks in first infestation; 1–3 days in re-infestation (already sensitised)"]),
 ("Why does itching start late and get worse at night?", ["Itch is a delayed (type IV) hypersensitivity to mite, eggs and faeces (scybala) — takes weeks to develop", "Nocturnal itch: warmth of bed increases mite activity and itch perception"]),
 ("Clinical features of classic scabies.", ["Generalised itching, worse at night, with other family members affected", "Burrows (pathognomonic): grey wavy thread-like lines 2–10 mm with a vesicle/dot at the end — web spaces of fingers, wrists, sides of fingers", "Papules, papulovesicles on finger webs, flexor wrists, elbows, anterior axillary folds, periumbilical, waist, buttocks, inner thighs, genitals (penile/scrotal nodules), areolae in women", "Circle of Hebra: imaginary circle through axillae, elbows, wrists, umbilicus, buttocks, genitals", "Head and neck spared in adults (involved in infants, elderly, immunosuppressed)"]),
 ("Scabies in infants — how is it different?", ["Face, scalp, palms and soles involved; vesicles, pustules, nodules (axillae, groin); irritability, poor feeding; often misdiagnosed as eczema or infantile acropustulosis"]),
 ("What is crusted (Norwegian) scabies?", ["Hyperinfestation in the immunosuppressed (HIV, HTLV-1, steroids, transplant), elderly, Down syndrome, leprosy, neurological disease with sensory loss", "Thick grey hyperkeratotic crusts and fissures on hands, feet, extensors, scalp, nails; little itch; highly contagious (millions of mites); can cause outbreaks in hospitals", "Treatment: oral ivermectin 200 µg/kg on days 1, 2, 8, 9, 15 (± 22, 29) + topical permethrin/benzyl benzoate with keratolytics; isolation and environment cleaning"]),
 ("Name other variants.", ["Nodular scabies (persistent itchy nodules on genitals/axillae; hypersensitivity; may last months after cure — intralesional/topical steroid)", "Bullous scabies (mimics bullous pemphigoid in elderly), scabies incognito (steroid-modified), scabies of the clean (few lesions), animal scabies (Sarcoptes from dogs — no burrows, self-limiting)", "Secondary: impetiginisation (post-streptococcal glomerulonephritis — major problem in endemic communities), eczematisation, urticarial"]),
 ("How do you confirm the diagnosis?", ["Clinical diagnosis using IACS 2020 criteria: confirmed (mite/eggs/faeces seen on microscopy or dermoscopy), clinical (burrows, male genital lesions, or typical lesions + itch + contact history), suspected", "Mineral oil scraping of a burrow → microscopy for mite, eggs, scybala", "Dermoscopy: 'delta-wing jet with contrail' sign (mite's head-legs triangle + burrow)", "Burrow ink test (ink fills the burrow)", "Skin biopsy rarely — mite in stratum corneum ('pigtail' of keratin), eosinophils"]),
 ("Differential diagnosis.", ["Papular urticaria/insect bites, atopic dermatitis, prurigo, dermatitis herpetiformis, pediculosis, folliculitis, bullous pemphigoid (elderly), infantile acropustulosis, Langerhans cell histiocytosis (infants), drug eruption, secondary syphilis (genital nodules)"]),
 ("Treatment of classic scabies.", ["Permethrin 5% cream: apply from neck down (include scalp/face in infants and elderly) to entire body including under nails, web spaces, genitals; wash after 8–14 h; repeat after 7 days — first line, safe from 2 months of age and in pregnancy", "Oral ivermectin 200 µg/kg single dose, repeated after 7 days (two doses; not ovicidal) — not for <15 kg children or pregnancy/lactation", "Alternatives: benzyl benzoate 25% (dilute for children; 3 applications), crotamiton 10% (weak, antipruritic), sulphur 5–10% in petrolatum (infants, pregnancy; 3 consecutive nights), malathion 0.5%; lindane — avoid (neurotoxic)"]),
 ("General measures for successful treatment.", ["Treat all household and close contacts at the same time, even without symptoms", "Wash clothes, bed linen and towels in hot water (≥50–60 °C) and dry in sun, or seal in a plastic bag for 72 h", "Cut nails; re-apply to hands if washed", "Antihistamines, emollients, mild steroids for post-scabetic itch; antibiotics for secondary infection"]),
 ("What is post-scabetic itch and how do you differentiate it from treatment failure?", ["Itch can persist 2–4 weeks after successful treatment due to ongoing hypersensitivity to dead mite antigens — no new burrows, gradually decreasing", "Failure/reinfestation: new burrows or lesions after 2–4 weeks, contacts not treated, incorrect application, resistance — re-treat (consider ivermectin + permethrin)"]),
 ("What is mass drug administration in scabies?", ["WHO strategy for endemic communities (prevalence >10%): ivermectin MDA (two doses 7 days apart) — reduces scabies and impetigo; scabies added to WHO NTD list in 2017"]),
 ("Mechanism of action of permethrin and ivermectin.", ["Permethrin: synthetic pyrethroid — blocks sodium channels in mite nerve membranes → paralysis and death; poorly absorbed, low toxicity", "Ivermectin: binds glutamate-gated chloride channels in invertebrate nerve and muscle → hyperpolarisation, paralysis; does not cross human blood–brain barrier (P-glycoprotein); not ovicidal hence second dose"]),
 ("Scabies in pregnancy and infants?", ["Permethrin 5% (safe), sulphur ointment; avoid ivermectin and lindane", "Infants under 2 months: sulphur 5% or crotamiton; apply to whole body including head"]),
 ],
 spot=["Burrows in finger webs + nocturnal itch + family affected — scabies", "Delta-wing jet sign on dermoscopy", "Crusted scabies — millions of mites, little itch, highly contagious"],
 note="Lindane withdrawal in India and ivermectin age/weight limits — please confirm with current guidance."),
]
